/*
 * Custom build: OpenCL shim for the GPU voice engine (ggml-opencl).
 * GENERATED by tools/gen_opencl_shim.py from tools/opencl_shim_template.c - edit those, not
 * opencl_shim.c.
 *
 * 1. Driver loading. Apps can't ship the GPU vendor's OpenCL driver, and linking straight to
 *    the phone's libOpenCL.so would make the whole voice engine fail to load on a phone that
 *    doesn't expose it. ggml-opencl links to this library instead; on first use it dlopen()s
 *    the phone's real driver and forwards every call to it. Without a driver,
 *    clGetPlatformIDs reports "no platforms" and voice input runs on the CPU.
 *
 * 2. Compiled-program cache. ggml compiles ~80 GPU programs from source every time the model
 *    is loaded (a ~5 s freeze on the S25 Ultra). The program functions below hand ggml a
 *    shim-owned handle; on clBuildProgram the shim loads a previously compiled binary from
 *    VOICE_CL_CACHE_DIR if one exists for exactly this source + build options + GPU + driver
 *    version, otherwise it compiles from source and saves the binary. Any problem with a
 *    cached binary falls back to compiling from source.
 */
#define CL_TARGET_OPENCL_VERSION 300
#define CL_USE_DEPRECATED_OPENCL_1_2_APIS
#include <CL/cl.h>
#include <CL/cl_ext.h>
#include <dlfcn.h>
#include <pthread.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

#ifndef CL_PLATFORM_NOT_FOUND_KHR
#define CL_PLATFORM_NOT_FOUND_KHR -1001
#endif

#define SHIM_EXPORT __attribute__((visibility("default")))

static void *g_driver = NULL;
static pthread_once_t g_once = PTHREAD_ONCE_INIT;

static void shim_load(void) {
    const char *override_path = getenv("VOICE_CL_DRIVER");  /* tests */
    const char *candidates[] = {
        override_path,
        "libOpenCL.so",                    /* resolved via <uses-native-library> (Android 12+) */
        "/vendor/lib64/libOpenCL.so",
        "/system/vendor/lib64/libOpenCL.so",
        "/vendor/lib64/libOpenCL_adreno.so",
        "libOpenCL.so.1",                  /* desktop Linux (tests) */
    };
    for (size_t i = 0; i < sizeof(candidates) / sizeof(candidates[0]) && !g_driver; i++) {
        if (candidates[i] && candidates[i][0]) g_driver = dlopen(candidates[i], RTLD_NOW | RTLD_LOCAL);
    }
}

static void *shim_sym(const char *name) {
    pthread_once(&g_once, shim_load);
    return g_driver ? dlsym(g_driver, name) : NULL;
}

